from typing import List

MOD = 10**18

def matrix_mult(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    return [[(A[0][0] * B[0][0] + A[0][1] * B[1][0]) % MOD, (A[0][0] * B[0][1] + A[0][1] * B[1][1]) % MOD],
            [(A[1][0] * B[0][0] + A[1][1] * B[1][0]) % MOD, (A[1][0] * B[0][1] + A[1][1] * B[1][1]) % MOD]]

def matrix_pow(matrix: List[List[int]], power: int) -> List[List[int]]:
    result = [[1, 0], [0, 1]]
    base = matrix
    while power > 0:
        if power % 2 == 1:
            result = matrix_mult(result, base)
        base = matrix_mult(base, base)
        power //= 2
    return result

def fibonacci(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    F = [[1, 1], [1, 0]]
    result = matrix_pow(F, n - 1)
    return result[0][0]

def contains_substring(num: int, sub: str) -> bool:
    num_str = str(num)
    return sub in num_str

def find_arithmetic_sequence(n: int, a: int, d: int) -> str:
    for b in range(1, 2**64):
        for e in range(1, 2**64):
            valid = True
            for i in range(n):
                fib_num = fibonacci(b + i * e)
                if not contains_substring(fib_num, str(a + i * d)):
                    valid = False
